#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* _multi_string_alloc_and_copy(const char** in, int count) {
    if (!in || count <= 0) {
        return NULL;
    }

    int total_len = 0;
    for (int i = 0; i < count; i++) {
        total_len += strlen(in[i]) + 1;
    }

    char* chr = malloc(total_len + 1);
    if (!chr) {
        return NULL;
    }

    char* dest = chr;
    for (int i = 0; i < count; i++) {
        strcpy(dest, in[i]);
        dest += strlen(in[i]) + 1;
    }

    *dest = '\0';

    return chr;
}
