#include <stdio.h>
#include <dirent.h>
#include <stdlib.h>
#include <string.h>

// Function to check if a string contains a specific substring
int containsSubstring(const char *str, const char *sub) {
    if (str == NULL || sub == NULL) return 0;
    return strstr(str, sub) != NULL;
}

// Recursive function to traverse the directory tree
int doTraversal(const char *path, int recursive, void (*xCallback)(const char *, void *), void *usr) {
    DIR *pdir;
    struct dirent *entry;
    pdir = opendir(path);
    if (pdir == NULL) {
        fprintf(stderr, "opendir error: %s\n", path);
        return 1;
    }

    while ((entry = readdir(pdir)) != NULL) {
        char tmp[1024];
        snprintf(tmp, sizeof(tmp), "%s/%s", path, entry->d_name);

        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        struct stat st;
        if (lstat(tmp, &st) == -1) {
            fprintf(stderr, "lstat error: %s\n", tmp);
            continue;
        }

        if (S_ISDIR(st.st_mode) && recursive) {
            doTraversal(tmp, recursive, xCallback, usr);
        } else if (S_ISREG(st.st_mode)) {
            if (xCallback != NULL) {
                xCallback(tmp, usr);
            }
        }
    }
    closedir(pdir);
    return 0;
}

// Callback function to count files containing a specific substring
void countFilesWithSubstring(const char *file, void *usr) {
    int *count = (int *)usr;
    FILE *fp = fopen(file, "r");
    if (fp == NULL) {
        fprintf(stderr, "fopen error: %s\n", file);
        return;
    }

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        if (containsSubstring(buffer, (const char *)usr)) {
            (*count)++;
            break;
        }
    }
    fclose(fp);
}

// Interface function to traverse the directory tree and count files with a specific substring
int dirTraversal(const char *path, int recursive, const char *substring) {
    int count = 0;
    doTraversal(path, recursive, countFilesWithSubstring, &substring);
    return count;
}
