int connect_socket(const char *protocol, const char *path, const char *name, int send_timeout, int recv_timeout)
{
	int sockfd = -1;
	struct sockaddr_un addr;
	if (0 > (sockfd = socket(AF_UNIX, SOCK_STREAM, 0))) {
		perror("socket()");
		return -1;
	}

	memset((void *)&addr, 0, sizeof(addr));
	addr.sun_family = AF_UNIX;
	strcpy(addr.sun_path, path);

	if (0 > connect(sockfd, (struct sockaddr *)&addr, sizeof(addr))) {
		perror("connect()");
		close(sockfd);
		return -1;
	}

	if (setsockopt(sockfd, SOL_SOCKET, SO_SNDTIMEO, (void *)&send_timeout, sizeof(send_timeout)) == -1) {
		perror("setsockopt(SO_SNDTIMEO)");
		close(sockfd);
		return -1;
	}

	if (setsockopt(sockfd, SOL_SOCKET, SO_RCVTIMEO, (void *)&recv_timeout, sizeof(recv_timeout)) == -1) {
		perror("setsockopt(SO_RCVTIMEO)");
		close(sockfd);
		return -1;
	}

	return sockfd;
}
