char* modify_string(char* input) {
    size_t len = strlen(input);
    if (len > 0) {
        if (input[len - 1] == '\n') {
            input[len - 1] = '\0';
        }
        if (len > 1 && input[len - 2] == '\r') {
            input[len - 2] = '\0';
        }
    }
    strcat(input, "\n");
    return input;
}

int main() {
    char test_string[] = "Hello, World!\n\r";
    printf("%s", modify_string(test_string));
    return 0;
