            else
            {
                CFE_EVS_SendEvent(CFE_FS_HEADER_WRITE_ERROR_EID, CFE_EVS_ERROR, "Error writing table header to file '%s', Status=0x%08X", FileName, Status);
                return CFE_FS_ERROR;
            }
        }
        else
        {
            CFE_EVS_SendEvent(CFE_FS_HEADER_WRITE_ERROR_EID, CFE_EVS_ERROR, "Error writing cFE header to file '%s', Status=0x%08X", FileName, Status);
            return CFE_FS_ERROR;
        }

        OS_close(FileDescriptor);
    }
    else
    {
        CFE_EVS_SendEvent(CFE_FS_CREATE_ERROR_EID, CFE_EVS_ERROR, "Error creating file '%s', Status=0x%08X", FileName, FileDescriptor);
        return CFE_FS_ERROR;
    }

    return CFE_FS_ERROR;
}
