                }
            }
            else
            {
                CFE_EVS_SendEvent(CFE_TBL_WRITE_TBL_HDR_ERR_EID,
                                  CFE_EVS_ERROR,
                                  "Error writing Tbl image File Header to '%s', Status=0x%08X",
                                  DumpFilename, Status);
            }
        }
        else
        {
