typedef int (*file_callback)(const char *path, void *usr);

int doTraversal(const char *path, int recursive, file_callback xCallback, void *usr) {
	DIR *pdir;
	struct dirent *pent;
	int res;

	pdir = opendir(path);
	if (pdir == NULL) {
		fprintf(stderr, "opendir error: %s\n", path);
		return 1;
	}

	while ((pent = readdir(pdir)) != NULL) {
