#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define HASH_TABLE_SIZE 1024

typedef struct pair_t {
    char *key;
    char *value;
    bool is_active;
    struct pair_t *next;
} pair_t;

typedef struct bucket_t {
    pair_t *head;
} bucket_t;

typedef struct hashtable_t {
    bucket_t *buckets;
    size_t size;
} hashtable_t;

size_t hash_str(const char *str) {
    size_t hash = 0;
    while (*str) {
        hash = (hash << 5) + *str++;
    }
    return hash % HASH_TABLE_SIZE;
}

pair_t *hashtable_find_pair(hashtable_t *hashtable, bucket_t *bucket, const char *key, size_t hash) {
    pair_t *pair = bucket->head;
    while (pair) {
        if (pair->hash == hash && strcmp(pair->key, key) == 0) {
            return pair;
        }
        pair = pair->next;
    }
    return NULL;
}

int hashtable_get(hashtable_t *hashtable, const char *key, char **value) {
    size_t hash = hash_str(key);
    bucket_t *bucket = &hashtable->buckets[hash & hashmask(hashtable->size)];
    pair_t *pair = hashtable_find_pair(hashtable, bucket, key, hash);
    if (pair && pair->is_active) {
        *value = strdup(pair->value);
        return pair->collision_count;
    }
    *value = NULL;
    return 0;
}

int hashmask(int order) {
    return (1 << order) - 1;
}
