import java.util.ArrayList;
import java.util.List;
import java.util.Random;

class PairProcessor {
    public void processPairs(List<Pair> pairs, double percentage) {
        Random random = new Random();
        int totalPairs = pairs.size();
        int targetPairs = (int) (totalPairs * percentage);

        for (int i = 0; i < totalPairs && i < targetPairs; i++) {
            Pair currentPair = pairs.get(i);
            if (i != totalPairs - 1) {
                int randomIndex = random.nextInt(i); // Select a previous pair randomly
                Pair previousPair = pairs.get(randomIndex);
                pairs.set(randomIndex, currentPair);
                pairs.set(i, previousPair);
            }
            System.out.println("Is this the last pair? " + (i == totalPairs - 1));
        }
    }

    static class Pair {
        int randomInt;
        boolean value;

        Pair(int randomInt, boolean value) {
            this.randomInt = randomInt;
            this.value = value;
        }
    }
}
