  private static void generateKeystore(String hostname, String storePassword, String keyPairPassword, String validity) throws IOException, InterruptedException {
    Path tempDir = Files.createTempDirectory("sslcertgen");
    Files.setPosixFilePermissions(tempDir, Collections.singleton(PosixFilePermission.OWNER_READ));

    Path keystorePath = tempDir.resolve("keystore");
    Files.setPosixFilePermissions(keystorePath, Collections.singleton(PosixFilePermission.OWNER_READ));

    ProcessBuilder processBuilder = new ProcessBuilder(
        "keytool",
        "-keystore", keystorePath.toString(),
        "-storepass", storePassword,
        "-genkeypair",
        "-alias", hostname,
        "-keyalg", "RSA",
        "-validity", validity,
        "-keypass", keyPairPassword,
        "-dname", "CN=" + hostname + ",OU=Gerrit Code Review,O=Example"
    );

    Process process = processBuilder.start();
    int exitCode = process.waitFor();
    if (exitCode != 0) {
      throw new IOException("Failed to generate keystore");
    }

    if (!keystorePath.toFile().renameTo(new File("keystore.jks"))) {
      throw new IOException("Failed to rename keystore");
    }

    if (!tempDir.toFile().delete()) {
      throw new IOException("Failed to delete temporary directory");
    }
  }
}
